import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>大多数压缩工具只提供固定的尺寸：50KB、100KB、200KB或500KB。但如果你的报名网站要求80KB、150KB，或者1.5MB呢？</p>\n<p>这就是<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>的工作。你输入需要的任意大小，工具会把图片压缩到正好命中那个数字。</p>\n<p>这篇指南会讲清楚自定义目标是怎么工作的、什么时候用它，以及怎样在任意大小下得到最好的画质。</p>\n<h2 id=\"what-is-target-compression\">什么是目标文件大小压缩？</h2>\n<p>目标压缩让你指定想要的精确文件大小，用KB或MB表示。工具再反过来工作，做出那个大小的文件。</p>\n<p>你可以输入80KB，应对上限不寻常的网站；也可以输入300KB，应对博客主题的特定预算。任何数字都可以。</p>\n<p>工具用的是和固定尺寸工具一样的二分画质搜索。它会测试不同的画质档位，直到找到能塞进你的数字的最高画质。</p>\n<p>只调画质达不到目标时，智能尺寸缩放会接着帮忙。工具会逐步缩小像素尺寸，直到达到目标。</p>\n<p>结果就是一个落在你选定的大小以下一点点的文件，画质是这个大小能装下的最好的。</p>\n<h2 id=\"how-it-works\">工具是怎么工作的？</h2>\n<p>在输入框里输入目标大小，选择KB或MB。切换单位时，工具会自动帮你换算。</p>\n<p>上传图片。支持JPG、PNG、WebP和HEIC文件，单个文件最大25MB。</p>\n<p>工具先在完整分辨率下运行画质搜索。只有搜索失败时，才会逐步缩小尺寸。</p>\n<p>汇总会显示每个文件的结果：目标、实际达到的大小，以及目标是达成还是没达成。</p>\n<p>批量模式能把多张图片一次压到同一个自定义目标。批量完成后，一起打包成ZIP下载。</p>\n<h2 id=\"kb-vs-mb\">KB与MB：选哪个单位？</h2>\n<p>KB适合小的目标。网站上限通常用KB表示，比如80KB或150KB，那就按网站写的数字原样输入。</p>\n<p>MB适合大的目标。1.5MB或2MB的目标用MB输入和阅读，比1536KB或2048KB容易得多。</p>\n<p>切换单位时会帮你重新计算。输入1MB再切换到KB，会显示1024KB，目标保持不变。</p>\n<p>小心四舍五入。网站说100KB通常是指102400字节，工具按精确字节数测量，保险起见。</p>\n<p>拿不准时，就用网站自己用的单位输入数字。和网站的说法保持一致，能避免换算错误。</p>\n<h2 id=\"when-to-use-custom\">什么时候用自定义目标？</h2>\n<p>不寻常的网站上限是主要原因。要求80KB或120KB的表格，固定尺寸工具服务不了。</p>\n<p>平台预算是另一个原因。博客主题或应用可能规定每张图片300KB，自定义目标能精确命中。</p>\n<p>测试是第三个原因。同一张图片分别压到100KB、150KB和200KB，能让你精确看到画质在哪里停止改善。</p>\n<p>邮件附件也能受益。一组图片必须总共小于5MB时，自定义目标能精确调校。</p>\n<p>固定工具覆盖的是常见尺寸。自定义工具覆盖的是其他一切，而这部分在真实工作里占的比例出乎意料地大。</p>\n<h2 id=\"binary-search-explained\">二分画质搜索，用大白话讲</h2>\n<p>工具不会猜一个画质数值。它会搜索最好的那一个，测试不同的画质档位，每次都把范围缩小。</p>\n<p>可以把它想象成在1到100之间猜数字。每次测试都会把剩下的范围砍掉一半，所以几步就能收敛。</p>\n<p>搜索先在完整分辨率下运行。这样能保护你的尺寸，对大多数人来说，尺寸比画质上的一点点差别更重要。</p>\n<p>只有完整尺寸下搜索失败时，缩放才开始。工具会测试更小的尺寸，在每一步上再次搜索最佳画质。</p>\n<p>结果就是，在你要的精确大小下，最清晰的那个版本。</p>\n<h2 id=\"dimension-scaling\">智能尺寸缩放</h2>\n<p>只降画质达不到目标时，尺寸缩放会缩小图片的像素尺寸。它是一小步一小步地降，而不是一下子跳到底。</p>\n<p>工具会测试90%、80%等缩放比例，在第一个能塞进目标的比例停下来。每一步都尽量保留最多的尺寸。</p>\n<p>小幅度的缩放通常看不出来。显示出来800像素宽的照片，720像素宽看起来一模一样。</p>\n<p>缩放对特别大的原图帮助最大。一张4000像素宽的照片，像素远超任何屏幕的需要，裁掉一点根本看不出来。</p>\n<p>网站要求精确像素时，你可以锁定尺寸。工具会更努力地只调画质，目标达不到时也会提醒你。</p>\n<h2 id=\"impossible-targets\">目标不可能达成时怎么办？</h2>\n<p>有些目标是达不到的。细节丰富的照片要压到2KB是不可能的，工具会诚实地告诉你，而不是递给你一个没用的文件。</p>\n<p>不可能的目标通常来自误解。网站要求2MB，被误读成2KB，就小了一千倍。</p>\n<p>固定尺寸会让目标更难。很大的像素尺寸加上很小的文件上限，可能真的做不到，任何工具都修不好。</p>\n<p>无损PNG是最难的。锁定PNG的细节图片可能永远塞不进小目标，不管你怎么缩小都没用。</p>\n<p>工具提示没达成时，改掉你能改的东西。换成JPG、允许缩放，或者裁得更紧一点，再跑一次。</p>\n<h2 id=\"formats-custom\">自定义目标的格式选择</h2>\n<p>JPG是自定义目标最安全的格式。它到处都被接受，任何大小下压缩照片的效率都很高。</p>\n<p>WebP在画质上常常略胜JPG。目的地接受它、而你又需要在很紧的目标下得到最锐利的结果时，就用它。</p>\n<p>PNG适合图形，不适合照片。标志或图表用PNG能做到像素级完美，照片用PNG则会浪费预算。</p>\n<p>自动转换选项在这里很有帮助。打开后，大的PNG照片会在压缩过程中自动转成JPG或WebP。</p>\n<p>透明图片需要做个决定。可能时用WebP保留透明背景，目的地要求时压平成白底JPG。</p>\n<h2 id=\"batch-custom\">批量压缩到自定义目标</h2>\n<p>批量模式能把多张图片一次压到同一个自定义目标。把文件夹拖进来，输入目标，让它跑就行。</p>\n<p>每张图片都是单独搜索的。简单的证件照和细节丰富的风景照会得到不同的画质设置，尽管它们共享同一个目标。</p>\n<p>汇总会记录部分成功的情况。如果三张文件达成了目标、一张没达成，汇总会精确显示哪一张需要注意。</p>\n<p>结果打包成ZIP下载。文件名会标明自定义目标，图片组保持整齐。</p>\n<p>批量自定义目标最适合上限不寻常的网站。五十张申请人照片全部压到80KB，几分钟就够了，不用几个小时。</p>\n<h2 id=\"common-mistakes\">自定义目标常见的错误</h2>\n<p>输错单位是最常见的错误。目标写成100MB而不是100KB，做出来的文件会大一千倍。</p>\n<p>设定不可能的目标会浪费时间。照片要压到3KB永远达不到，工具也会这样告诉你。</p>\n<p>忘记检查结果也很常见。文件大小对了，图片却可能是糊的，所以下载之前先预览。</p>\n<p>反复压缩已经压缩过的文件会叠加损伤。即使目标很宽裕，也要从原图开始。</p>\n<p>最后，别以为每个网站都接受WebP。先确认接受的格式，不然你可能要压缩两次。</p>\n<h2 id=\"privacy-custom\">自定义目标的隐私</h2>\n<p>所有压缩都在你的浏览器里进行。照片在本地处理，永远不会上传到服务器。</p>\n<p>这对自定义目标很重要，它们常常服务于合同、医疗扫描和客户样稿这样的敏感文件。</p>\n<p>相机的GPS标签和EXIF数据会在压缩过程中被去掉。下载下来的文件不记录照片在哪里、什么时候拍的。</p>\n<p>对敏感工作来说，这种隐私本身就是一个功能。你可以压缩机密的批量，不用担心还有谁会看到它。</p>\n<p>分享之前，一定要再检查一遍下载好的文件。处理过程的隐私不能代替分享时的细心。</p>\n<h2 id=\"unit-mistakes\">单位错误及避免方法</h2>\n<p>自定义压缩里代价最高的错误就是单位错误。把100KB写成100MB，目标会大一千倍。</p>\n<p>网站的上限一定要读两遍。数字和单位分开记，再分开输入到工具里。</p>\n<p>输入之后，上传之前再读一遍。快速看一眼，就能发现少了小数点或多了个零。</p>\n<p>记住1MB等于1024KB，不是1000KB。工具用的是二进制定义，和操作系统测量文件的方式一致。</p>\n<p>结果看起来错得离谱时，先检查单位。十次里有九次，问题出在单位上，而不是工具上。</p>\n<h2 id=\"target-for-email\">邮件附件的自定义目标</h2>\n<p>邮件系统常常把附件上限设在每封20MB或25MB。一组图片必须塞进这个上限时，自定义目标能帮上忙。</p>\n<p>用上限除以图片数量，算出每张文件的预算。十张图片共享20MB的上限，每张分到2MB。</p>\n<p>目标设得比精确除法稍微小一点。留出安全余量，应对四舍五入，让总和稳稳地低于上限。</p>\n<p>把批量压到自定义目标，检查ZIP的总大小。超过上限时，降低目标再跑一次。</p>\n<p>只有一张图片时，上限很少是问题。一张500KB的照片发起来很容易，一张5MB的可能会被退回。</p>\n<h2 id=\"target-for-print-prep\">用自定义目标准备打印图片</h2>\n<p>打印店有时会规定上传的最大文件大小。自定义目标能精确命中这个数字，不用猜。</p>\n<p>记住打印需要的是分辨率，而不只是文件大小。低分辨率的2MB文件印出来依然很差，不管文件多大。</p>\n<p>准备打印时，尺寸保持高一点。让工具只调画质，目标要求时才允许缩放。</p>\n<p>条件允许时，检查打印样张。屏幕预览会藏住问题，纸张会暴露出来，尤其是平滑区域的色带。</p>\n<p>最终交付打印时，打印店接受原图就发原图。自定义目标是为上传上限准备的，不是为印刷机准备的。</p>\n<h2 id=\"comparing-targets\">同一张图片比较多个目标</h2>\n<p>同一张图片用几个目标各跑一次，能让你看到画质在哪里停止改善。分别压到100KB、200KB和500KB，再对比。</p>\n<p>三张都用全尺寸查看。从100KB到200KB的提升通常看得见，从200KB到500KB的提升常常看不见。</p>\n<p>这个对比能告诉你看起来还不错的最小尺寸。以后同类图片都用这个尺寸，每张都能省带宽。</p>\n<p>对比文件留着做参考。它们成了你以后为类似图片选择目标的指南。</p>\n<p>测试只要几分钟，回报却能持续几个月。测试过的目标每次都胜过猜出来的目标。</p>\n<h2 id=\"saving-presets\">保存常用的目标</h2>\n<p>大多数人反复用的就是那几个目标。这个月要80KB的网站，下个月还是要80KB。</p>\n<p>把常用目标和用途记在一份简短的清单里。exam portal 80KB、blog hero 300KB这样的一句短注，能省掉重新读规则的麻烦。</p>\n<p>把工具加入收藏夹时，心里记着目标。工具在两次访问之间什么都不记得，你的清单就是它的记忆。</p>\n<p>把清单分享给团队。共享的目标清单能让每个人不再各自猜测。</p>\n<p>规则变了就检查清单。网站会更新上限，旧目标可能变成被拒绝的上传。</p>\n<h2 id=\"accessibility-custom\">自定义目标的无障碍</h2>\n<p>压缩后的图片依然要服务每一位观众。把目标定得太紧、文字都模糊了，需要读文字的读者就看不下去了。</p>\n<p>压缩后检查对比度和可读性。文字叠加和小标签在你选定的目标下必须保持清晰。</p>\n<p>网上用的压缩图片一定要加替代文字。一个小文件配上好的替代文字，比一个完美却没有替代文字的文件服务到更多人。</p>\n<p>文字重要时，优先选更大的目标。多出来的KB保护了可读性，这比更小的文件更值得。</p>\n<p>压缩和无障碍是一回事。清晰、高对比的原图既压得更好，也让每个观众都更容易读懂。</p>\n<p>想看动手操作的步骤，可以读<a href=\"/zh/blog/ru-he-ba-tu-pian-ya-suo-dao-jing-que-kb-da-xiao/\">如何把图片压缩到精确的KB大小</a>。想深入了解搜索本身，可以看<a href=\"/zh/blog/jing-que-kb-mu-biao-er-fen-zhi-liang-sou-suo-jie-xi/\">精确KB目标：二分画质搜索详解</a>。固定尺寸合用时，<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>和<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>覆盖了常见的上限。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"目标压缩工具里能输入多大的尺寸范围？","answer":"任何自定义大小都可以，用KB或MB输入，从几KB到几MB都行。2KB或3KB这样特别小的目标，细节丰富的照片通常达不到，工具会诚实地告诉你目标没法实现。"},{"question":"最终文件大小和我的目标有多接近？","answer":"非常接近。工具会按精确字节数瞄准目标以下一点点，通常落在目标的几KB以内。留出这点安全余量，是为了避开不同系统之间字节四舍五入的差异。"},{"question":"能把一批照片压到同一个自定义大小吗？","answer":"可以。一次加入多张图片，每张都会被压到同一个自定义目标，然后打包成ZIP一起下载。汇总会显示哪些文件达成了目标、哪些没达成，没达成的可以单独修复。"},{"question":"上传的图片已经比我的目标小了，会怎么样？","answer":"工具会提醒你，重新压缩反而会让文件变大。比目标小的图片本来就没问题，直接用它就行，不要强行压缩、徒增损伤。"},{"question":"为什么工具先测试画质，再缩小尺寸？","answer":"降低画质能保住像素数，对大多数人来说，像素数比画质上的一点点差别更重要。只有画质不够时，尺寸缩放才会开始。这个顺序能让图片尽可能大、尽可能锐利。"},{"question":"用固定尺寸工具好，还是自定义目标工具好？","answer":"固定尺寸合用时用固定工具，点一下更快。网站或平台要求不寻常的尺寸时，或者你想测试几个尺寸、找到图片的最佳平衡点时，用自定义工具。"}];
